\cite{vershynin2018highdim}
\label{lem:product}
Let \(X\) and \(Y\) be sub-Gaussian random variables, not necessarily
independent. Then \(XY\) is sub-exponential and
$
    \|XY\|_{\psi_1}
    \lesssim
    \|X\|_{\psi_2}\|Y\|_{\psi_2}.
$

\label{lem:prev_dual_eq}
Fix any \(\lambda\in\mathbb{R}^m\) and \(T\subseteq\mathbb{R}^m\). Let
\(G\in\mathbb{R}^{k\times m}\) have i.i.d.\ entries distributed as
\(N(0,1/k)\). Then, for every \(u\geq 1\), with probability at least
\(1-Ce^{-cu}\) for some universal constants \(c,C>0\),
\begin{align*}
\sup_{\mathbf{t}\in T}
\left|
\left\langle
(G^\top G-I_m)\lambda,\mathbf{t}
\right\rangle
\right|
\lesssim
\|\lambda\|_2
\left(
\frac{1}{\sqrt{k}}
+
\frac{\sqrt{u}}{k}
\right)
\left[
\gamma_2(T,\|\cdot\|_2)
+
\operatorname{rad}(T)\sqrt{u}
\right].
\end{align*}

\label{lem:prev_dual_ineq}
Fix \(\lambda\in\mathbb{R}^m\) and a nonempty set
\(T\subseteq\mathbb{R}^m\). Let
\(G\in\mathbb{R}^{k\times m}\) have i.i.d.\ entries distributed as
\(N(0,1/k)\), and let \(G^+\) denote the entrywise positive part of \(G\).
Then there exist universal constants \(c,C>0\) such that, for every
\(u\geq1\), with probability at least \(1-Ce^{-cu}\),

$$
\sup_{\mathbf{t}\in T}
\left|
\left\langle
\bigl(2G^\top G^+-I_m\bigr)\lambda,\mathbf{t}
\right\rangle
\right|
\lesssim
\left(\|\lambda\|_1+\|\lambda\|_2\right)
\left[
\frac{
\gamma_2(T,\|\cdot\|_2)
+
\operatorname{rad}(T)\sqrt{u}
}{\sqrt{k}}
+
\frac{
\gamma_1(T,\|\cdot\|_2)
+
\operatorname{rad}(T)u
}{k}
\right].
$$
